import {SKILLS,clamp} from './core.js';
// Orthographic software view. The same gameplay simulation is used in both views.
export class CompatibilityView {
  constructor(canvas,game,settings){this.canvas=canvas;this.game=game;this.settings=settings;this.ctx=canvas.getContext('2d');if(!this.ctx)throw new Error('Canvas 2D unavailable');this.fx=[];this.floating=[];game.on('release',e=>this.fx.push({...e,type:'release',age:0,life:e.id==='nova'?.55:.6}));game.on('impact',e=>this.fx.push({...e,type:'impact',age:0,life:1.1}));game.on('hit',e=>this.floating.push({...e,life:1.1}));game.on('reset',()=>{this.fx=[];this.floating=[];});this.resize();}
  resize(){this.w=this.canvas.parentElement.clientWidth;this.h=this.canvas.parentElement.clientHeight;const dpr=Math.min(window.devicePixelRatio||1,1.5);this.canvas.width=Math.round(this.w*dpr);this.canvas.height=Math.round(this.h*dpr);this.ctx.setTransform(dpr,0,0,dpr,0,0);this.scale=Math.min(this.w/32,this.h/26);}
  project(x,y,z){return{x:this.w/2+(x-z)*this.scale*.72,y:this.h*.45+(x+z)*this.scale*.36-y*this.scale*.95,visible:true};}
  aim(clientX,clientY){const r=this.canvas.getBoundingClientRect(),a=(clientX-r.left-this.w/2)/this.scale/.72,b=(clientY-r.top-this.h*.45)/this.scale/.36;this.game.setAim((a+b)/2,(b-a)/2);}
  polygon(points,fill,stroke){const c=this.ctx;c.beginPath();points.forEach(([x,y,z],i)=>{const p=this.project(x,y,z);i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y);});c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=.8;c.stroke();}}
  line(points,color,width=1){const c=this.ctx;c.beginPath();points.forEach(([x,y,z],i)=>{const p=this.project(x,y,z);i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y);});c.strokeStyle=color;c.lineWidth=width;c.stroke();}
  ring(x,z,r,color,alpha=1,y=.02){const c=this.ctx;c.save();c.globalAlpha=alpha;const points=Array.from({length:65},(_,i)=>{const a=i/64*Math.PI*2;return[x+Math.sin(a)*r,y,z+Math.cos(a)*r];});this.line(points,color,1.1);c.restore();}
  glow(x,y,z,size,color,alpha=1){const p=this.project(x,y,z),c=this.ctx;c.save();c.globalAlpha=alpha;const g=c.createRadialGradient(p.x,p.y,0,p.x,p.y,size*this.scale);g.addColorStop(0,color);g.addColorStop(.15,color+'aa');g.addColorStop(1,color+'00');c.fillStyle=g;c.fillRect(p.x-size*this.scale,p.y-size*this.scale,size*this.scale*2,size*this.scale*2);c.restore();}
  prism(x,z,width,height,color='#263d49',y=0){const h=width/2;this.polygon([[x-h,y,z-h],[x+h,y,z-h],[x+h,y+height,z-h],[x-h,y+height,z-h]],color,'#ffffff09');this.polygon([[x+h,y,z-h],[x+h,y,z+h],[x+h,y+height,z+h],[x+h,y+height,z-h]],'#152831','#ffffff0c');this.polygon([[x-h,y+height,z-h],[x+h,y+height,z-h],[x+h,y+height,z+h],[x-h,y+height,z+h]],'#3d535d','#8cd0c322');}
  drawMage(p){const c=this.ctx,t=this.game.time,a=p.angle,dx=Math.sin(a),dz=Math.cos(a);this.ring(p.x,p.z,.8,'#a0e6cf',.6);this.glow(p.x,.02,p.z,1.4,'#64dfc1',.1);const body=this.project(p.x,0,p.z);c.save();c.fillStyle='#0005';c.beginPath();c.ellipse(body.x,body.y+2,this.scale*.5,this.scale*.18,0,0,Math.PI*2);c.fill();c.restore();const walk=Math.sin(t*10)*p.moving*.2;this.prism(p.x-.18,p.z+walk,.17,.55,'#1c303d');this.prism(p.x+.18,p.z-walk,.17,.55,'#1c303d');this.polygon([[p.x-.46,.45,p.z-.25],[p.x+.46,.45,p.z-.25],[p.x+.29,1.55,p.z],[p.x-.29,1.55,p.z]],'#28757c','#a5d6c455');this.polygon([[p.x-.36,.45,p.z-.22],[p.x+.3,.45,p.z-.22],[p.x+.22,1.6,p.z-.2],[p.x-.22,1.6,p.z-.2]],'#153f50','#66b6aa44');this.prism(p.x,p.z,.4,.39,'#152c36',1.6);const head=this.project(p.x,2.1,p.z);c.fillStyle='#3c8383';c.beginPath();c.moveTo(head.x,head.y-this.scale*.23);c.lineTo(head.x-this.scale*.26,head.y+this.scale*.16);c.lineTo(head.x+this.scale*.23,head.y+this.scale*.16);c.closePath();c.fill();const staffx=p.x+dx*.55+dz*.35,staffz=p.z+dz*.55-dx*.35;const rise=p.cast?.45:0;this.line([[staffx,.1+rise,staffz],[staffx,2.4+rise,staffz]],'#bca67a',2.3);const color=p.cast?SKILLS[p.cast.id].color:'#a1ffde';this.glow(staffx,2.35+rise,staffz,p.cast?1.2:.6,color,.8);const gem=this.project(staffx,2.35+rise,staffz);c.fillStyle=color;c.beginPath();c.moveTo(gem.x,gem.y-7);c.lineTo(gem.x+4,gem.y);c.lineTo(gem.x,gem.y+7);c.lineTo(gem.x-4,gem.y);c.closePath();c.fill();if(p.cast){this.ring(p.x,p.z,1+p.cast.elapsed/p.cast.duration,'#c7f9eb',.6);}}
  render(dt){const c=this.ctx,g=this.game,t=g.time;const bg=c.createRadialGradient(this.w*.5,this.h*.35,0,this.w*.5,this.h*.4,this.w*.8);bg.addColorStop(0,'#1b3541');bg.addColorStop(.7,'#0b1925');bg.addColorStop(1,'#071018');c.fillStyle=bg;c.fillRect(0,0,this.w,this.h);
    const floor=Array.from({length:96},(_,i)=>{const a=i/96*Math.PI*2;return[Math.sin(a)*13.7,-.12,Math.cos(a)*13.7];});this.polygon(floor,'#162732','#42605e');c.save();const platform=new Path2D();floor.forEach(([x,y,z],i)=>{const p=this.project(x,y,z);i?platform.lineTo(p.x,p.y):platform.moveTo(p.x,p.y);});platform.closePath();c.clip(platform);for(let i=-14;i<=14;i++){this.line([[i,0,-15],[i,0,15]],i===0?'#30494e':'#20363f',.6);this.line([[-15,0,i],[15,0,i]],i===0?'#30494e':'#20363f',.6);}c.restore();for(const r of [13.3,12.7,10.5])this.ring(0,0,r,r===13.3?'#81d8c0':'#446b6a',r===13.3?.9:.6);
    for(let i=0;i<40;i++){const a=i*Math.PI/20;const r=12.7;this.line([[Math.sin(a)*r,.02,Math.cos(a)*r],[Math.sin(a)*(r-.22),.02,Math.cos(a)*(r-.22)]],'#79b4aa',1);}
    const actors=[...g.targets.map(target=>({type:'target',data:target,x:target.x,z:target.z})),{type:'mage',data:g.player,x:g.player.x,z:g.player.z}];for(let i=0;i<12;i++){const a=i*Math.PI/6;actors.push({type:'pillar',x:Math.sin(a)*13.6,z:Math.cos(a)*13.6});}actors.sort((a,b)=>a.x+a.z-b.x-b.z);
    for(const a of actors){if(a.type==='pillar'){this.prism(a.x,a.z,.75,1.55);this.glow(a.x,1.9,a.z,.9,'#7bddca',.65);const p=this.project(a.x,1.9,a.z);c.fillStyle='#b0ffec';c.beginPath();c.moveTo(p.x,p.y-8);c.lineTo(p.x+4,p.y);c.lineTo(p.x,p.y+8);c.lineTo(p.x-4,p.y);c.fill();}else if(a.type==='mage'){this.drawMage(a.data);}else{const target=a.data;if(target.hp<=0)continue;this.ring(a.x,a.z,.65,'#729794',.65);this.prism(a.x,a.z,.45,.6,'#203340');this.prism(a.x,a.z,.6,1,'#405b68',.7);this.prism(a.x,a.z,.25,.35,'#bbad86',1.85);this.glow(a.x,1.4,a.z,.65,target.flash?'#ffc9aa':'#78b7be',target.flash?.7:.15);const p=this.project(a.x,2.6,a.z);c.fillStyle='#152d35';c.fillRect(p.x-16,p.y,32,2);c.fillStyle='#acddbe';c.fillRect(p.x-16,p.y,32*target.hp/target.maxHp,2);}}
    const radius=g.selected==='nova'?SKILLS.nova.radius:.55;this.ring(g.aim.x,g.aim.z,radius,SKILLS[g.selected].color,.8);this.ring(g.aim.x,g.aim.z,radius+.13,SKILLS[g.selected].color,.25);
    for(const b of g.projectiles){this.glow(b.x,1.45,b.z,1.3,'#ffab69',.8);const p=this.project(b.x,1.45,b.z);c.fillStyle='#fff4d4';c.beginPath();c.arc(p.x,p.y,3,0,Math.PI*2);c.fill();for(let j=1;j<6;j++)this.glow(b.x-b.dx*j*.18,1.45,b.z-b.dz*j*.18,.25,'#ff9455',.8-j*.12);}
    this.fx=this.fx.filter(f=>{if(!g.paused)f.age+=dt;const p=clamp(f.age/f.life,0,1),kind=f.kind||f.id,color=SKILLS[kind]?.color||'#c1a1ff';if(f.type==='impact'){const radius=kind==='nova'?3.8:1.1;this.ring(f.x,f.z,(.1+p*1.2)*radius,color,1-p);this.ring(f.x,f.z,(.1+p)*radius,color,(1-p)*.5);this.glow(f.x,.4,f.z,radius*2,color,(1-p)**3);for(let j=0;j<Math.round(22*this.settings.intensity);j++){const a=j*2.4;this.glow(f.x+Math.sin(a)*p*radius,Math.sin(p*Math.PI)*(j%4+1)*.5,f.z+Math.cos(a)*p*radius,.12,color,1-p);}}else if(f.id==='beam'){c.save();c.shadowBlur=18;c.shadowColor=color;this.line([[f.origin.x,1.45,f.origin.z],[f.end.x,1.45,f.end.z]],color,10*(1-p));this.line([[f.origin.x,1.45,f.origin.z],[f.end.x,1.45,f.end.z]],'#ebffff',2*(1-p));c.restore();}else if(f.id==='nova'){this.ring(f.aim.x,f.aim.z,3.8,color,.65);this.glow(f.aim.x,13*(1-p),f.aim.z,1.4,color,.9);}return p<1;});
    for(let i=0;i<50;i++){const x=Math.sin(i*21.4)*14,z=Math.cos(i*6.15)*14,y=(i*.25+t*.18)%8;const p=this.project(x,y,z);c.fillStyle='#a7dbcc'+(i%2?'55':'22');c.fillRect(p.x,p.y,1,1);}
    if(!g.paused)for(const n of this.floating)n.life-=dt;this.floating=this.floating.filter(n=>n.life>0);return this.floating.map(n=>({...this.project(n.x,3+(1-n.life)*1.2,n.z),text:n.damage,color:SKILLS[n.kind].color,alpha:Math.min(1,n.life*3)}));
  }
}
